            keyed_update_t cut1_q [8];
            keyed_update_t cut2_d [8];
            keyed_update_t cut2_q [8];
            keyed_update_t cut3_d [8];
            keyed_update_t cut3_q [8];

            assign o_valid = valid_pipe[LATENCY - 1];

            always_ff @(posedge clk) begin
                if (rst) begin
                    valid_pipe <= '0;
                    for (int i = 0; i < 8; i++) begin
                        cut0_q[i] <= '0;
                        cut1_q[i] <= '0;
                        cut2_q[i] <= '0;
                        cut3_q[i] <= '0;
                    end
                end else begin
                    valid_pipe[0] <= i_valid;
                    valid_pipe[1] <= valid_pipe[0];
                    valid_pipe[2] <= valid_pipe[1];
                    valid_pipe[3] <= valid_pipe[2];
                    for (int i = 0; i < 8; i++) begin
                        cut0_q[i] <= cut0_d[i];
                        cut1_q[i] <= cut1_d[i];
                        cut2_q[i] <= cut2_d[i];
                        cut3_q[i] <= cut3_d[i];
                    end
                end
            end

            always_comb begin
                keyed_update_t stage0 [8];
                keyed_update_t stage1 [8];
                keyed_update_t stage2 [8];
                keyed_update_t stage3 [8];
                keyed_update_t stage4 [8];
                keyed_update_t stage5 [8];
                keyed_update_t stage6 [8];
                keyed_pair_t pair;

                for (int i = 0; i < 8; i++) begin
                    o_updates[i] = '0;
                    cut0_d[i] = '0;
                    cut1_d[i] = '0;
                    cut2_d[i] = '0;
                    cut3_d[i] = '0;
                end

                for (int i = 0; i < 8; i++) begin
                    stage0[i].update = i_updates[i];
