            keyed_update_t cut2_d [8];
            keyed_update_t cut2_q [8];
            keyed_update_t cut3_d [8];
            keyed_update_t cut3_q [8];
            keyed_update_t cut4_d [8];
            keyed_update_t cut4_q [8];
            keyed_update_t cut5_d [8];
            keyed_update_t cut5_q [8];

            assign o_valid = valid_pipe[LATENCY - 1];

            always_ff @(posedge clk) begin
                if (rst) begin
                    valid_pipe <= '0;
                    for (int i = 0; i < 8; i++) begin
                        cut0_q[i] <= '0;
                        cut1_q[i] <= '0;
                        cut2_q[i] <= '0;
                        cut3_q[i] <= '0;
                        cut4_q[i] <= '0;
                        cut5_q[i] <= '0;
                    end
                end else begin
                    valid_pipe[0] <= i_valid;
                    valid_pipe[1] <= valid_pipe[0];
                    valid_pipe[2] <= valid_pipe[1];
                    valid_pipe[3] <= valid_pipe[2];
                    valid_pipe[4] <= valid_pipe[3];
                    valid_pipe[5] <= valid_pipe[4];
                    for (int i = 0; i < 8; i++) begin
                        cut0_q[i] <= cut0_d[i];
                        cut1_q[i] <= cut1_d[i];
                        cut2_q[i] <= cut2_d[i];
                        cut3_q[i] <= cut3_d[i];
                        cut4_q[i] <= cut4_d[i];
                        cut5_q[i] <= cut5_d[i];
                    end
