                pair = ce_pair(stage2[10], stage2[12]); stage2[10] = pair.lo; stage2[12] = pair.hi;
                pair = ce_pair(stage2[11], stage2[13]); stage2[11] = pair.lo; stage2[13] = pair.hi;

                for (int i = 0; i < 14; i++) begin
                    cut1_d[i] = stage2[i];
                end

                stage3 = cut1_q;
                pair = ce_pair(stage3[0], stage3[10]); stage3[0] = pair.lo; stage3[10] = pair.hi;
                pair = ce_pair(stage3[1], stage3[6]); stage3[1] = pair.lo; stage3[6] = pair.hi;
                pair = ce_pair(stage3[2], stage3[11]); stage3[2] = pair.lo; stage3[11] = pair.hi;
                pair = ce_pair(stage3[3], stage3[13]); stage3[3] = pair.lo; stage3[13] = pair.hi;
                pair = ce_pair(stage3[5], stage3[8]); stage3[5] = pair.lo; stage3[8] = pair.hi;
                pair = ce_pair(stage3[7], stage3[12]); stage3[7] = pair.lo; stage3[12] = pair.hi;

                for (int i = 0; i < 14; i++) begin
                    cut2_d[i] = stage3[i];
                end

                stage4 = cut2_q;
                pair = ce_pair(stage4[1], stage4[4]); stage4[1] = pair.lo; stage4[4] = pair.hi;
                pair = ce_pair(stage4[2], stage4[8]); stage4[2] = pair.lo; stage4[8] = pair.hi;
                pair = ce_pair(stage4[3], stage4[6]); stage4[3] = pair.lo; stage4[6] = pair.hi;
                pair = ce_pair(stage4[5], stage4[11]); stage4[5] = pair.lo; stage4[11] = pair.hi;
                pair = ce_pair(stage4[7], stage4[10]); stage4[7] = pair.lo; stage4[10] = pair.hi;
                pair = ce_pair(stage4[9], stage4[12]); stage4[9] = pair.lo; stage4[12] = pair.hi;

                for (int i = 0; i < 14; i++) begin
                    cut3_d[i] = stage4[i];
                end

                stage5 = cut3_q;
                pair = ce_pair(stage5[0], stage5[1]); stage5[0] = pair.lo; stage5[1] = pair.hi;
                pair = ce_pair(stage5[3], stage5[9]); stage5[3] = pair.lo; stage5[9] = pair.hi;
                pair = ce_pair(stage5[4], stage5[10]); stage5[4] = pair.lo; stage5[10] = pair.hi;
                pair = ce_pair(stage5[5], stage5[7]); stage5[5] = pair.lo; stage5[7] = pair.hi;
                pair = ce_pair(stage5[6], stage5[8]); stage5[6] = pair.lo; stage5[8] = pair.hi;
                pair = ce_pair(stage5[12], stage5[13]); stage5[12] = pair.lo; stage5[13] = pair.hi;

                for (int i = 0; i < 14; i++) begin
                    cut4_d[i] = stage5[i];
                end

                stage6 = cut4_q;
                pair = ce_pair(stage6[1], stage6[5]); stage6[1] = pair.lo; stage6[5] = pair.hi;
                pair = ce_pair(stage6[2], stage6[4]); stage6[2] = pair.lo; stage6[4] = pair.hi;
                pair = ce_pair(stage6[3], stage6[7]); stage6[3] = pair.lo; stage6[7] = pair.hi;
                pair = ce_pair(stage6[6], stage6[10]); stage6[6] = pair.lo; stage6[10] = pair.hi;
                pair = ce_pair(stage6[8], stage6[12]); stage6[8] = pair.lo; stage6[12] = pair.hi;
                pair = ce_pair(stage6[9], stage6[11]); stage6[9] = pair.lo; stage6[11] = pair.hi;

                for (int i = 0; i < 14; i++) begin
                    cut5_d[i] = stage6[i];
                end

                stage7 = cut5_q;
                pair = ce_pair(stage7[1], stage7[2]); stage7[1] = pair.lo; stage7[2] = pair.hi;
                pair = ce_pair(stage7[3], stage7[5]); stage7[3] = pair.lo; stage7[5] = pair.hi;
                pair = ce_pair(stage7[4], stage7[6]); stage7[4] = pair.lo; stage7[6] = pair.hi;
                pair = ce_pair(stage7[7], stage7[9]); stage7[7] = pair.lo; stage7[9] = pair.hi;
                pair = ce_pair(stage7[8], stage7[10]); stage7[8] = pair.lo; stage7[10] = pair.hi;
                pair = ce_pair(stage7[11], stage7[12]); stage7[11] = pair.lo; stage7[12] = pair.hi;

                for (int i = 0; i < 14; i++) begin
                    cut6_d[i] = stage7[i];
                end

                stage8 = cut6_q;
                pair = ce_pair(stage8[2], stage8[3]); stage8[2] = pair.lo; stage8[3] = pair.hi;
                pair = ce_pair(stage8[4], stage8[5]); stage8[4] = pair.lo; stage8[5] = pair.hi;
                pair = ce_pair(stage8[6], stage8[7]); stage8[6] = pair.lo; stage8[7] = pair.hi;
                pair = ce_pair(stage8[8], stage8[9]); stage8[8] = pair.lo; stage8[9] = pair.hi;
                pair = ce_pair(stage8[10], stage8[11]); stage8[10] = pair.lo; stage8[11] = pair.hi;

                for (int i = 0; i < 14; i++) begin
                    cut7_d[i] = stage8[i];
                end

                stage9 = cut7_q;
                pair = ce_pair(stage9[3], stage9[4]); stage9[3] = pair.lo; stage9[4] = pair.hi;
                pair = ce_pair(stage9[5], stage9[6]); stage9[5] = pair.lo; stage9[6] = pair.hi;
                pair = ce_pair(stage9[7], stage9[8]); stage9[7] = pair.lo; stage9[8] = pair.hi;
                pair = ce_pair(stage9[9], stage9[10]); stage9[9] = pair.lo; stage9[10] = pair.hi;

                for (int i = 0; i < 14; i++) begin
                    cut8_d[i] = stage9[i];
                end

                for (int i = 0; i < 14; i++) begin
                    o_updates[i] = cut8_q[i].update;
                end
            end
        end else begin : gen_default
            assign o_valid = i_valid;

            always_comb begin
                for (int i = 0; i < PIPE_WIDTH; i++) begin
                    o_updates[i] = i_updates[i];
                end
            end
        end
    endgenerate
endmodule

